import numpy as np
import pandas as pd
from pytest import approx
from trazione import modulo_elastico


def curva(E=200e3, fy=350.0, n=400):
    eps = np.linspace(0, 0.08, n)
    sig = np.where(eps < fy / E, E * eps, fy + 1500 * (eps - fy / E) ** 0.6)
    return pd.DataFrame({"eps": eps, "sigma": sig})


def test_modulo():
    assert modulo_elastico(curva(), 50, 250) == approx(200e3, rel=1e-6)
